begin;
create extension if not exists pgtap with schema extensions;
select plan(24);
select ok(to_regclass('public.school_schedule_entries') is not null, 'school timetable table exists');
select ok(to_regclass('public.school_calendar_events') is not null, 'school calendar table exists');
select ok(to_regclass('public.school_operations_audit_events') is not null, 'school operations audit table exists');
select ok((select relrowsecurity from pg_class where oid='public.school_schedule_entries'::regclass), 'timetable has RLS enabled');
select ok((select relrowsecurity from pg_class where oid='public.school_calendar_events'::regclass), 'calendar has RLS enabled');
select ok((select relrowsecurity from pg_class where oid='public.school_operations_audit_events'::regclass), 'operations audit has RLS enabled');
select ok(exists(select 1 from pg_policies where schemaname='public' and tablename='school_schedule_entries' and policyname='school_schedule_entries_read' and cmd='SELECT'), 'timetable has an explicit scoped read policy');
select ok(exists(select 1 from pg_policies where schemaname='public' and tablename='school_calendar_events' and policyname='school_calendar_events_read' and cmd='SELECT'), 'calendar has audience-aware read policy');
select ok(exists(select 1 from pg_policies where schemaname='public' and tablename='school_operations_audit_events' and policyname='school_operations_audit_events_read' and cmd='SELECT'), 'audit reads are manager/admin scoped');
select ok(has_table_privilege('authenticated','public.school_schedule_entries','SELECT'), 'authenticated role can read timetable through RLS');
select ok(has_table_privilege('authenticated','public.school_calendar_events','SELECT'), 'authenticated role can read calendar through RLS');
select ok(not has_table_privilege('authenticated','public.school_schedule_entries','INSERT'), 'authenticated role cannot write timetable directly');
select ok(not has_table_privilege('authenticated','public.school_calendar_events','UPDATE'), 'authenticated role cannot edit calendar directly');
select ok(not has_table_privilege('anon','public.school_calendar_events','SELECT'), 'anonymous role cannot read school calendar');
select ok(has_function_privilege('authenticated','public.school_manager_save_schedule_entry(uuid,uuid,uuid,uuid,text,smallint,time,time,text,date,date,text,text,uuid)','execute'), 'authenticated role can call guarded timetable RPC');
select ok(has_function_privilege('authenticated','public.school_manager_save_calendar_event(uuid,text,text,text,timestamptz,timestamptz,boolean,text,text,text,uuid,text,text,uuid)','execute'), 'authenticated role can call guarded calendar RPC');
select ok(not has_function_privilege('anon','public.school_manager_save_schedule_entry(uuid,uuid,uuid,uuid,text,smallint,time,time,text,date,date,text,text,uuid)','execute'), 'anonymous role cannot call timetable RPC');
select ok(not has_function_privilege('anon','public.school_manager_save_calendar_event(uuid,text,text,text,timestamptz,timestamptz,boolean,text,text,text,uuid,text,text,uuid)','execute'), 'anonymous role cannot call calendar RPC');
select ok(exists(select 1 from pg_constraint where conrelid='public.school_schedule_entries'::regclass and conname='school_schedule_time_check'), 'timetable rejects non-positive lesson durations');
select ok(exists(select 1 from pg_constraint where conrelid='public.school_schedule_entries'::regclass and conname='school_schedule_effective_dates_check'), 'timetable validates effective date ranges');
select ok(exists(select 1 from pg_constraint where conrelid='public.school_calendar_events'::regclass and conname='school_calendar_event_audience_check'), 'calendar validates audience scope');
select ok(exists(select 1 from pg_trigger where tgrelid='public.school_operations_audit_events'::regclass and tgname='school_operations_audit_events_immutable' and not tgisinternal), 'operations audit records are immutable');
select ok(exists(select 1 from pg_indexes where schemaname='public' and indexname='school_schedule_entries_scope_idx'), 'timetable has a school/section query index');
select ok(exists(select 1 from pg_indexes where schemaname='public' and indexname='school_calendar_events_scope_idx'), 'calendar has a school/date query index');
select * from finish();
rollback;
